describe('Card Number Validation - Invalid Input', () => {
  beforeEach(() => {
    cy.visit('/payment');
  });

  it('should display error message when user enters an invalid card number', () => {
    // Intercept the API call to validate card number
    cy.intercept('POST', '/api/validate-card', {
      statusCode: 200,
      body: {
        isValid: false,
        error: 'Invalid card number format'
      }
    }).as('validateCard');

    // Get the card input field
    cy.get('[data-testid="card-number-input"]').type('1234567890123456');

    // Submit the form
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for the API response
    cy.wait('@validateCard');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid card number format');

    // Verify error class is applied to the input
    cy.get('[data-testid="card-number-input"]')
      .should('have.class', 'error');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]')
      .should('not.exist');
  });

  it('should clear error message when user corrects the card number', () => {
    // Intercept the API call to validate card number
    cy.intercept('POST', '/api/validate-card', {
      statusCode: 200,
      body: {
        isValid: false,
        error: 'Invalid card number format'
      }
    }).as('validateCard');

    // Get the card input field
    cy.get('[data-testid="card-number-input"]').type('1234567890123456');

    // Submit the form
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for the API response
    cy.wait('@validateCard');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid card number format');

    // Clear the error message
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Get the card input field again
    cy.get('[data-testid="card-number-input"]').should('have.value', '');

    // Type a valid card number
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');

    // Submit the form again
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for the API response
    cy.wait('@validateCard');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Payment successful');

    // Verify error message is no longer visible
    cy.get('[data-testid="error-message"]')
      .should('not.exist');
  });
});
